function ccParseColor(str){
  str=String(str||'').trim();
  var m;
  if((m=str.match(/^#([0-9a-f]{3}|[0-9a-f]{6})$/i))){
    var h=m[1];
    if(h.length===3) h=h[0]+h[0]+h[1]+h[1]+h[2]+h[2];
    return {r:parseInt(h.slice(0,2),16), g:parseInt(h.slice(2,4),16), b:parseInt(h.slice(4,6),16)};
  }
  if((m=str.match(/^rgb\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*\)$/i))){
    return {r:+m[1], g:+m[2], b:+m[3]};
  }
  return null;
}
function ccLin(c){
  c=c/255;
  return c<=0.03928 ? c/12.92 : Math.pow((c+0.055)/1.055, 2.4);
}
function ccLum(c){
  return 0.2126*ccLin(c.r)+0.7152*ccLin(c.g)+0.0722*ccLin(c.b);
}
function ccContrast(fg, bg){
  var l1=ccLum(fg), l2=ccLum(bg);
  var hi=Math.max(l1,l2), lo=Math.min(l1,l2);
  return Math.round((hi+0.05)/(lo+0.05)*100)/100;
}
function ccLevel(ratio){
  return { AA: ratio>=4.5, AALarge: ratio>=3, AAA: ratio>=7, AAALarge: ratio>=4.5 };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { ccParseColor:ccParseColor, ccLum:ccLum, ccContrast:ccContrast, ccLevel:ccLevel };
}
if (typeof window !== 'undefined') {
  window.ColorContrastForgePure = { ccParseColor:ccParseColor, ccLum:ccLum, ccContrast:ccContrast, ccLevel:ccLevel };
}
